<?php
$pdo=db();$userScope=is_admin()?'':' AND user_id='.(int)current_user()['id'];$today=$pdo->query("SELECT COALESCE(SUM(grand_total),0) sales,COUNT(*) orders FROM orders WHERE DATE(created_at)=CURDATE() AND status='Selesai'".$userScope)->fetch();
$best=$pdo->query("SELECT d.product_name,SUM(d.quantity) qty FROM order_details d JOIN orders o ON o.id=d.order_id WHERE DATE(o.created_at)=CURDATE() AND o.status='Selesai'".(is_admin()?'':' AND o.user_id='.(int)current_user()['id'])." GROUP BY d.product_id,d.product_name ORDER BY qty DESC LIMIT 1")->fetch();
$low=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE status=1 AND stock<=10')->fetchColumn();
$recent=orders(is_admin()?'':'AND o.user_id=?',is_admin()?[]:[current_user()['id']],6);
$chart=$pdo->query("SELECT DATE_FORMAT(days.day,'%a') label,COALESCE(SUM(o.grand_total),0) amount FROM (SELECT CURDATE() - INTERVAL seq DAY AS day FROM (SELECT 0 seq UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6) n) days LEFT JOIN orders o ON DATE(o.created_at)=days.day AND o.status='Selesai'".(is_admin()?'':' AND o.user_id='.(int)current_user()['id'])." GROUP BY days.day ORDER BY days.day")->fetchAll();$max=max(array_column($chart,'amount')?:[1]);
?>
<div class="page-heading"><div><p class="eyebrow"><?= is_admin()?'PANTAU KINERJA KAFE':'AKTIVITAS SHIFT ANDA' ?></p><h1><?= is_admin()?'Semua terasa terkendali.':'Selamat bertugas, '.e(explode(' ',current_user()['name'])[0]).'.' ?></h1><p class="subheading">Ringkasan operasional untuk <?= date('l, d F Y') ?>.</p></div><a class="button primary" href="index.php?page=new-order"><span>＋</span> Buat pesanan</a></div>
<div class="stats-grid"><article class="stat-card sales-card"><div class="stat-top"><span class="stat-label">Omset hari ini</span><span class="stat-icon">↗</span></div><strong><?= rupiah($today['sales']) ?></strong><small>Pesanan yang telah selesai</small><div class="stat-mark">01</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Pesanan selesai</span><span class="stat-icon mint">▤</span></div><strong><?= (int)$today['orders'] ?></strong><small>Transaksi hari ini</small></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Menu terlaris</span><span class="stat-icon gold">✳</span></div><strong class="stat-menu"><?= e($best['product_name']??'Belum ada') ?></strong><small><?= $best?(int)$best['qty'].' porsi terjual hari ini':'Belum ada penjualan selesai' ?></small></article><article class="stat-card <?= $low?'warning-card':'' ?>"><div class="stat-top"><span class="stat-label">Stok menipis</span><span class="stat-icon coral">!</span></div><strong><?= $low ?></strong><small>Menu dengan stok ≤ 10</small></article></div>
<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h2>Penjualan pekan ini</h2><p>Omset dari transaksi selesai · 7 hari</p></div><?php if(is_admin()):?><a class="text-link" href="index.php?page=reports">Lihat laporan <span>→</span></a><?php endif;?></div><div class="chart-wrap"><div class="chart-y"><span>Rp <?= number_format($max/1000000,1,',','.') ?> jt</span><span>Rp <?= number_format($max/2/1000,0,',','.') ?> rb</span><span>Rp 0</span></div><div class="bars"><?php foreach($chart as $d):$height=$max>0?max(5,(float)$d['amount']/$max*100):5;?><div class="bar-column"><div class="bar-value"><?= $d['amount']?rupiah($d['amount']):'–' ?></div><div class="bar-track"><span style="height:<?= $height ?>%" title="<?= rupiah($d['amount']) ?>"></span></div><small><?= e($d['label']) ?></small></div><?php endforeach;?></div></div></section><section class="panel quick-panel"><div class="panel-heading"><div><h2>Langkah cepat</h2><p>Yang sering dibutuhkan di jam sibuk.</p></div></div><a class="quick-action" href="index.php?page=new-order"><span class="quick-icon">＋</span><span><strong>Catat pesanan baru</strong><small>Mulai transaksi meja atau takeaway</small></span><b>→</b></a><a class="quick-action" href="index.php?page=orders"><span class="quick-icon soft">▤</span><span><strong>Lihat daftar pesanan</strong><small>Pantau status pesanan yang masuk</small></span><b>→</b></a><?php if(is_admin()):?><a class="quick-action" href="index.php?page=reports"><span class="quick-icon warm">▥</span><span><strong>Buka laporan penjualan</strong><small>Rekap menurut tanggal dan metode</small></span><b>→</b></a><?php endif;?><?php if($low):?><div class="stock-alert"><span>!</span><div><strong><?= $low ?> menu perlu perhatian</strong><small>Periksa stok sebelum shift berikutnya.</small></div><?php if(is_admin()):?><a href="index.php?page=menu">Cek</a><?php endif;?></div><?php endif;?></section></div>
<section class="panel recent-panel"><div class="panel-heading"><div><h2>Pesanan terbaru</h2><p><?= is_admin()?'Aktivitas terbaru semua kasir.':'Riwayat transaksi shift Anda.' ?></p></div><a class="text-link" href="index.php?page=orders">Semua pesanan <span>→</span></a></div><?php if(!$recent):?><div class="empty-state"><span>▤</span><strong>Belum ada pesanan hari ini</strong><p>Pesanan baru akan muncul di sini.</p></div><?php else:?><div class="table-scroll"><table><thead><tr><th>Invoice</th><th>Pemesan / meja</th><?php if(is_admin()):?><th>Kasir</th><?php endif;?><th>Waktu</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $o):?><tr><td><a class="invoice-link" href="index.php?page=receipt&id=<?= (int)$o['id'] ?>"><?= e($o['invoice_number']) ?></a></td><td><?= e($o['customer_name']?:($o['order_type']==='Dine-In'?'Meja '.$o['table_number']:'Takeaway')) ?></td><?php if(is_admin()):?><td><?= e($o['cashier']) ?></td><?php endif;?><td><?= date('H:i',strtotime($o['created_at'])) ?></td><td class="money-cell"><?= rupiah($o['grand_total']) ?></td><td><span class="status <?= $o['status']==='Selesai'?'done':($o['status']==='Dibatalkan'?'cancelled':'pending') ?>"><?= e($o['status']) ?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
